CREATE TABLE IF NOT EXISTS mcp_oauth_clients (id TEXT PRIMARY KEY, client_id TEXT NOT NULL UNIQUE, client_name TEXT, redirect_uris TEXT NOT NULL DEFAULT '[]', client_secret_hash TEXT, token_endpoint_auth_method TEXT NOT NULL DEFAULT 'client_secret_basic', created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());
CREATE TABLE IF NOT EXISTS mcp_oauth_pending_requests (id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL, client_name TEXT, redirect_uri TEXT NOT NULL, state TEXT, scope TEXT NOT NULL DEFAULT 'mcp:read', code_challenge TEXT NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());
CREATE INDEX IF NOT EXISTS mcp_oauth_pending_requests_expires_idx ON mcp_oauth_pending_requests (expires_at);
CREATE TABLE IF NOT EXISTS mcp_oauth_codes (id TEXT PRIMARY KEY, code_hash TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL, user_id TEXT NOT NULL, redirect_uri TEXT NOT NULL, code_challenge TEXT NOT NULL, scope TEXT NOT NULL DEFAULT 'mcp:read', used_at TIMESTAMP WITH TIME ZONE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());
CREATE INDEX IF NOT EXISTS mcp_oauth_codes_expires_idx ON mcp_oauth_codes (expires_at);
CREATE TABLE IF NOT EXISTS mcp_oauth_refresh_tokens (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, family_id TEXT NOT NULL, client_id TEXT NOT NULL, user_id TEXT NOT NULL, scope TEXT NOT NULL DEFAULT 'mcp:read', used_at TIMESTAMP WITH TIME ZONE, revoked_at TIMESTAMP WITH TIME ZONE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());
CREATE INDEX IF NOT EXISTS mcp_oauth_refresh_tokens_family_idx ON mcp_oauth_refresh_tokens (family_id);
CREATE INDEX IF NOT EXISTS mcp_oauth_refresh_tokens_user_idx ON mcp_oauth_refresh_tokens (user_id);
CREATE TABLE IF NOT EXISTS mcp_service_principals (id TEXT PRIMARY KEY, name TEXT NOT NULL, key_hash TEXT UNIQUE, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());
